mapper.update:
UPDATE BOARD
SET B_HITS = B_HITS + 1
WHERE B_IDX = #{b_idx}

mapper.select:
SELECT COUNT(1) 
FROM HEART 
WHERE H_U_IDX = #{h_u_idx} AND H_B_IDX = #{h_b_idx}

mapper.update:
    	UPDATE BOARD
		SET B_TITLE = #{b_title}, B_CONTENT = #{b_content} , B_MODIFY = CURRENT_TIMESTAMP
		WHERE B_IDX = #{b_idx}

mapper.delete:
    	UPDATE BOARD
		SET B_DELETE = 'Y'
		WHERE B_IDX=#{b_idx}

mapper.update:
UPDATE BOARD
SET B_VOTE = 'Y'
WHERE B_IDX = #{v_b_idx}

mapper.select:
    	SELECT IFNULL(
			(SELECT VR.VR_VO_IDX
			FROM VOTE_RESULT VR
			  JOIN VOTE_OPTION VO ON VR.VR_VO_IDX = VO.VO_IDX
			  JOIN VOTE VT ON VO.VO_V_IDX = VT.V_IDX
			WHERE VT.V_B_IDX = #{v_b_idx}
			  AND VR.VR_U_IDX = #{vr_u_idx}
			  LIMIT 1
			), 0) AS USER_VOTE_OPTION

mapper.update:
UPDATE VOTE_OPTION
SET VO_COUNT = VO_COUNT + 1
WHERE VO_IDX = #{vr_vo_idx}
